const STORAGE_KEY="capivaras_ficha_tecnica_v2";
const AUTH_KEY="capivaras_admin_logado";
const MARKUP=3;
let state={ingredientes:[],custos:[],receitas:[],config:{horasProdutivasMes:220,cardapioUrl:""}};
let pedidoVisaoAtual="geral";
let perfilAtual={role:"anon",nome:"",ativo:false,local:true};
const ROLE_TABS={anon:[],admin:["dashboard","ingredientes","custos","receitas","simulador","treinamento","qrcode","pedidos","mesas","dados"],bar:["pedidos","treinamento"],cozinha:["pedidos","treinamento"]};
const $=s=>document.querySelector(s);
const $$=s=>Array.from(document.querySelectorAll(s));

document.addEventListener("DOMContentLoaded",async()=>{await carregarDados();migrarDados();configurarAbas();configurarEventos();if(!$("#listaIngredientesReceita").children.length)adicionarLinhaIngredienteReceita();await configurarLogin();atualizarTudo(false);});

function supabaseConfigurado(){return !!window.CapivarasData?.isSupabaseConfigured?.();}
function roleAtual(){return perfilAtual?.role||"anon";}
function podeAcessarAba(tab){return(ROLE_TABS[roleAtual()]||[]).includes(tab);}
function exigirAdmin(){if(roleAtual()==="admin")return true;mostrarToast("Seu perfil não tem permissão para esta ação.");return false;}
async function configurarLogin(){const usandoSupabase=supabaseConfigurado();$("#loginTexto").textContent=usandoSupabase?"Entre com o usuário cadastrado no Supabase Auth.":"Acesso local provisório para gestão das fichas técnicas.";$("#loginHint").textContent=usandoSupabase?"O acesso depende da tabela profiles e do role ativo.":"Fallback local: admin · capivaras123";$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();const u=$("#loginUsuario").value.trim(),s=$("#loginSenha").value.trim();if(usandoSupabase){try{const data=await CapivarasData.signIn(u,s);const perfil=await carregarPerfilSupabase(data?.user||data?.session?.user);if(!perfil)return;await recarregarDadosSupabasePosLogin();abrirAdmin(perfil);atualizarTudo(false);mostrarToast("Bem-vindo ao admin Capivaras.");}catch(err){mostrarToast("Login Supabase inválido ou sem perfil ativo.");}return;}if(u==="admin"&&s==="capivaras123"){sessionStorage.setItem(AUTH_KEY,"true");abrirAdmin({role:"admin",nome:"Administrador local",ativo:true,local:true});atualizarTudo(false);mostrarToast("Bem-vindo ao admin Capivaras.");}else mostrarToast("Usuário ou senha inválidos.");});$("#logoutBtn").addEventListener("click",async()=>{if(supabaseConfigurado())await CapivarasData.signOut().catch(()=>{});sessionStorage.removeItem(AUTH_KEY);location.reload();});if(usandoSupabase){const session=await CapivarasData.getSession().catch(()=>null);if(session){const perfil=await carregarPerfilSupabase(session.user);if(perfil){await recarregarDadosSupabasePosLogin();abrirAdmin(perfil);return;}}mostrarLogin();return;}const logado=sessionStorage.getItem(AUTH_KEY)==="true";if(logado)abrirAdmin({role:"admin",nome:"Administrador local",ativo:true,local:true});else mostrarLogin();}
async function recarregarDadosSupabasePosLogin(){if(!supabaseConfigurado())return;state=await CapivarasData.carregarDoSupabase(state).catch(()=>state);migrarDados();}
async function carregarPerfilSupabase(user){try{const perfil=await CapivarasData.carregarPerfilUsuario(user);if(!perfil||!perfil.ativo){mostrarToast("Usuário sem perfil ativo.");return null;}if(!["admin","bar","cozinha"].includes(perfil.role)){mostrarToast("Perfil com role inválido.");return null;}return perfil;}catch{mostrarToast("Não foi possível buscar o perfil do usuário.");return null;}}
function mostrarLogin(){perfilAtual={role:"anon",nome:"",ativo:false,local:true};$("#loginScreen").classList.remove("hidden");$("#adminApp").classList.add("hidden");}
function abrirAdmin(perfil){perfilAtual={...perfil,role:perfil.role||"admin"};$("#loginScreen").classList.add("hidden");$("#adminApp").classList.remove("hidden");aplicarPermissoesPerfil();}
function aplicarPermissoesPerfil(){const role=roleAtual();$("#perfilAtual").textContent=`Perfil: ${role}${perfilAtual.nome?` · ${perfilAtual.nome}`:""}`;$$(".nav-btn").forEach(btn=>btn.classList.toggle("role-hidden",!podeAcessarAba(btn.dataset.tab)));const admin=role==="admin";["#carregarCsvPadrao",".markup-pill"].forEach(sel=>$$(sel).forEach(el=>el.classList.toggle("role-hidden",!admin)));const configCard=$("#modoAtendimento")?.closest(".card");if(configCard)configCard.classList.toggle("role-hidden",!admin);$$("[data-pedido-view]").forEach(btn=>{const permitido=admin||btn.dataset.pedidoView===role;btn.classList.toggle("role-hidden",!permitido);btn.classList.toggle("active",(admin&&btn.dataset.pedidoView===pedidoVisaoAtual)||(!admin&&btn.dataset.pedidoView===role));});if(!admin)pedidoVisaoAtual=role;const active=$(".nav-btn.active");if(!active||!podeAcessarAba(active.dataset.tab)){const first=$$(".nav-btn").find(btn=>podeAcessarAba(btn.dataset.tab));if(first)selecionarAba(first.dataset.tab);}}
function selecionarAba(tab){if(!podeAcessarAba(tab)){mostrarToast("Seu perfil não tem acesso a esta área.");return;}$$(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));$$(".tab-content").forEach(t=>t.classList.toggle("active",t.id===tab));if(tab==="simulador")renderSimulador();if(tab==="qrcode")prepararQr();if(tab==="pedidos")renderPedidosAdmin();if(tab==="mesas")renderMesasQr();}
function configurarAbas(){$$(".nav-btn").forEach(btn=>btn.addEventListener("click",()=>selecionarAba(btn.dataset.tab)));}
function configurarEventos(){
  $("#formIngrediente").addEventListener("submit",salvarIngrediente);$("#cancelarEdicaoIngrediente").addEventListener("click",limparFormIngrediente);["ingredienteQuantidade","ingredienteUnidadeCompra","ingredienteCustoTotal"].forEach(id=>$("#"+id).addEventListener("input",atualizarPreviewIngrediente));$("#buscaIngredientes").addEventListener("input",renderIngredientes);
  $("#formCusto").addEventListener("submit",salvarCusto);$("#cancelarEdicaoCusto").addEventListener("click",limparFormCusto);$("#custoValorMensal").addEventListener("input",atualizarPreviewCustos);$("#salvarConfigCustos").addEventListener("click",salvarConfigCustos);$("#horasProdutivasMes").addEventListener("input",atualizarPreviewCustos);
  $("#formReceita").addEventListener("submit",salvarReceita);$("#cancelarEdicaoReceita").addEventListener("click",limparFormReceita);$("#adicionarIngredienteReceita").addEventListener("click",()=>adicionarLinhaIngredienteReceita());$("#listaIngredientesReceita").addEventListener("input",atualizarPreviewReceita);$("#listaIngredientesReceita").addEventListener("change",atualizarPreviewReceita);$("#buscaReceitas").addEventListener("input",renderReceitas);["receitaTempoPreparo","receitaPrecoFinal","receitaAtivoCardapio","receitaDescricaoCardapio","receitaFotoUrl","receitaSetorPreparo"].forEach(id=>$("#"+id).addEventListener("input",atualizarPreviewReceita));$("#receitaFotoInput").addEventListener("change",carregarFotoProduto);$("#removerFotoProduto").addEventListener("click",removerFotoProduto);$("#importarReceitasCsv").addEventListener("click",importarReceitasCsvManual);
  $("#simuladorProduto").addEventListener("change",renderSimuladorResultado);$("#buscaTreinamento").addEventListener("input",renderTreinamento);$("#filtroCategoriaTreinamento").addEventListener("change",renderTreinamento);$("#gerarQrCode").addEventListener("click",gerarQrCode);$("#cardapioUrl").addEventListener("input",()=>{state.config.cardapioUrl=$("#cardapioUrl").value.trim();salvarDados();});
  $("#salvarConfigAtendimento").addEventListener("click",salvarConfigAtendimento);["filtroPedidoMesa","filtroPedidoStatus","filtroPedidoData","filtroPedidoCobranca"].forEach(id=>$("#"+id).addEventListener("input",renderPedidosAdmin));$$("[data-pedido-view]").forEach(btn=>btn.addEventListener("click",()=>{pedidoVisaoAtual=btn.dataset.pedidoView;$$("[data-pedido-view]").forEach(b=>b.classList.remove("active"));btn.classList.add("active");renderPedidosAdmin();}));$("#gerarMesas").addEventListener("click",gerarMesasAdmin);
  $("#exportarJson").addEventListener("click",exportarJson);$("#importarJson").addEventListener("click",importarJson);$("#limparDados").addEventListener("click",limparTodosDados);$("#carregarCsvPadrao").addEventListener("click",importarCsvDiretorio);$("#importarCsvDiretorio").addEventListener("click",importarCsvDiretorio);$("#importarCsvManual").addEventListener("click",importarCsvManual);$("#exportarCsv").addEventListener("click",exportarCsvIngredientes);$("#exportarCardapioJson").addEventListener("click",exportarCardapioJson);
  ["ingredienteCustoTotal","custoValorMensal","receitaPrecoFinal"].forEach(id=>$("#"+id).addEventListener("blur",e=>{const v=parseMoeda(e.target.value);e.target.value=v?v.toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2}):"";}));
}
function salvarDados(){try{if(window.CapivarasData){CapivarasData.salvarDados(state);if(CapivarasData.isSupabaseConfigured())CapivarasData.salvarCardapioPublico(dadosCardapio().receitas).catch(()=>{});return;}localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}}
async function carregarDados(){try{if(window.CapivarasData){state=await CapivarasData.carregarDados(state);return;}const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=JSON.parse(raw);}catch{mostrarToast("Erro ao carregar dados salvos.");}}
function migrarDados(){state.ingredientes=Array.isArray(state.ingredientes)?state.ingredientes:[];state.custos=Array.isArray(state.custos)?state.custos:[];state.receitas=Array.isArray(state.receitas)?state.receitas:[];state.config=state.config||{};if(state.config.horasProdutivasMes===undefined||state.config.horasProdutivasMes===null||state.config.horasProdutivasMes==="")state.config.horasProdutivasMes=220;if(!state.config.cardapioUrl)state.config.cardapioUrl="";state.ingredientes=state.ingredientes.map(i=>({...i,codigo:i.codigo||i.cod||i["Cód."]||""}));state.receitas=state.receitas.map(r=>({...r,ativoCardapio:!!r.ativoCardapio,descricaoCardapio:r.descricaoCardapio||"",fotoProduto:r.fotoProduto||"",fotoUrl:r.fotoUrl||"",precoFinalManual:Number(r.precoFinalManual||0),setorPreparo:normalizarSetorPreparo(r.setorPreparo||"auto"),tempoPreparoMin:tempoParaMinutos(r.tempoPreparoMin??r.tempoPreparo)}));salvarDados();}
function atualizarTudo(save=true){if(save)salvarDados();renderIngredientes();renderCustos();renderReceitas();renderDashboard();renderTreinamento();renderResumoDados();atualizarSelectsIngredientes();atualizarPreviewIngrediente();atualizarPreviewCustos();atualizarPreviewReceita();renderSimulador();prepararQr();renderConfigAtendimento();renderPedidosAdmin();renderMesasQr();}
function gerarId(p="id"){return p+"_"+Date.now().toString(36)+Math.random().toString(36).slice(2,7);}function textoSeguro(v){const d=document.createElement("div");d.textContent=v??"";return d.innerHTML;}function parseMoeda(v){if(typeof v==="number")return v;if(!v)return 0;let s=String(v).replace(/[R$\s]/g,"").trim();if(s==="-"||s==="")return 0;if(s.includes(",")){s=s.replace(/\./g,"").replace(",",".");}return Number(s)||0;}function formatarMoeda(v){return(Number(v)||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});}function formatarCustoBase(v){return(Number(v)||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL",minimumFractionDigits:4,maximumFractionDigits:5});}function formatarNumero(v){return(Number(v)||0).toLocaleString("pt-BR",{maximumFractionDigits:3});}function mostrarToast(msg){const t=$("#toast");t.textContent=msg;t.classList.remove("hidden");clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.add("hidden"),2800);}function normalizarUnidade(u){u=String(u||"").trim().toLowerCase();if(["gr","grama","gramas","g"].includes(u))return"g";if(["kg","quilo","quilos"].includes(u))return"kg";if(["ml","mililitro","mililitros"].includes(u))return"ml";if(["l","lt","litro","litros"].includes(u))return"litro";if(["un","und","unid","unidade","unidades"].includes(u))return"unidade";return u||"unidade";}function unidadeBase(u){u=normalizarUnidade(u);if(u==="kg"||u==="g")return"g";if(u==="litro"||u==="ml")return"ml";return"unidade";}function quantidadeBase(q,u){q=Number(q)||0;u=normalizarUnidade(u);if(u==="kg"||u==="litro")return q*1000;return q;}function custoUnitarioIngrediente(i){const base=quantidadeBase(i.quantidade,i.unidadeCompra);return base>0?Number(i.custoTotal||0)/base:0;}function tempoParaMinutos(v){if(v===undefined||v===null||v==="")return 0;if(typeof v==="number")return v;const n=Number(String(v).replace(",",".").match(/[0-9.]+/)?.[0]||0);return n||0;}function totalCustosFixos(){return state.custos.reduce((a,c)=>a+Number(c.valorMensal||0),0);}function custoOperacionalMinuto(){const h=Number(state.config.horasProdutivasMes||0);return h>0?totalCustosFixos()/(h*60):0;}function arredondarCima050(v){return Math.ceil((Number(v)||0)/0.5)*0.5;}function classeMargem(m){return m>=70?"margin-green":m>=50?"margin-yellow":"margin-red";}function normalizarSetorPreparo(v){return window.AtendimentoStore?AtendimentoStore.normalizarSetorPreparo(v):(["bar","cozinha","ambos"].includes(String(v||"").toLowerCase())?String(v).toLowerCase():"auto");}function labelSetorPreparo(v){return({auto:"Automático",bar:"Bar",cozinha:"Cozinha",ambos:"Ambos"})[normalizarSetorPreparo(v)]||"Automático";}
function calcularReceita(r){let custoIngredientes=0,incompleta=false;(r.ingredientes||[]).forEach(item=>{const ing=state.ingredientes.find(i=>i.id===item.ingredienteId||String(i.codigo||"")===String(item.codigo||""));if(!ing){incompleta=true;return;}const base=unidadeBase(ing.unidadeCompra),un=normalizarUnidade(item.unidade||base);if(base!==un){incompleta=true;return;}custoIngredientes+=custoUnitarioIngrediente(ing)*Number(item.quantidade||0);});const tempo=tempoParaMinutos(r.tempoPreparoMin??r.tempoPreparo);const custoTempo=tempo*custoOperacionalMinuto();const custoTotal=custoIngredientes+custoTempo;const precoSugeridoBruto=custoTotal*MARKUP;const precoArredondado=arredondarCima050(precoSugeridoBruto);const precoFinal=Number(r.precoFinalManual||0)>0?Number(r.precoFinalManual):precoArredondado;const lucroBruto=precoFinal-custoTotal;const margem=precoFinal>0?(lucroBruto/precoFinal)*100:0;const markupReal=custoTotal>0?precoFinal/custoTotal:0;return{custoIngredientes,custoTempo,custoTotal,precoSugeridoBruto,precoArredondado,precoFinal,lucroBruto,margem,markupReal,incompleta,tempo};}
function salvarIngrediente(e){e.preventDefault();if(!exigirAdmin())return;const id=$("#ingredienteId").value,nome=$("#ingredienteNome").value.trim(),codigo=$("#ingredienteCodigo").value.trim(),unidadeCompra=normalizarUnidade($("#ingredienteUnidadeCompra").value),quantidade=Number($("#ingredienteQuantidade").value),custoTotal=parseMoeda($("#ingredienteCustoTotal").value);if(!nome||!unidadeCompra||quantidade<=0||custoTotal<=0){mostrarToast("Preencha corretamente o ingrediente.");return;}const ingrediente={id:id||gerarId("ing"),codigo,nome,unidadeCompra,quantidade,custoTotal,origem:id?"editado":"manual",atualizadoEm:new Date().toISOString()};state.ingredientes=id?state.ingredientes.map(i=>i.id===id?ingrediente:i):[...state.ingredientes,ingrediente];limparFormIngrediente();atualizarTudo();mostrarToast(id?"Ingrediente atualizado.":"Ingrediente cadastrado.");}
function editarIngrediente(id){if(!exigirAdmin())return;const i=state.ingredientes.find(x=>x.id===id);if(!i)return;$("#ingredienteId").value=i.id;$("#ingredienteCodigo").value=i.codigo||"";$("#ingredienteNome").value=i.nome;$("#ingredienteUnidadeCompra").value=i.unidadeCompra;$("#ingredienteQuantidade").value=i.quantidade;$("#ingredienteCustoTotal").value=Number(i.custoTotal).toLocaleString("pt-BR",{minimumFractionDigits:2});$("#cancelarEdicaoIngrediente").classList.remove("hidden");document.querySelector('[data-tab="ingredientes"]').click();atualizarPreviewIngrediente();}
function excluirIngrediente(id){if(!exigirAdmin())return;if(!confirm("Excluir este ingrediente?"))return;state.ingredientes=state.ingredientes.filter(i=>i.id!==id);atualizarTudo();mostrarToast("Ingrediente excluído.");}function limparFormIngrediente(){$("#formIngrediente").reset();$("#ingredienteId").value="";$("#cancelarEdicaoIngrediente").classList.add("hidden");atualizarPreviewIngrediente();}
function atualizarPreviewIngrediente(){const q=Number($("#ingredienteQuantidade").value),u=$("#ingredienteUnidadeCompra").value,c=parseMoeda($("#ingredienteCustoTotal").value),base=quantidadeBase(q,u),un=unidadeBase(u),valor=base>0?c/base:0;$("#previewCustoIngrediente").textContent=`${formatarCustoBase(valor)} / ${un}`;}
function renderIngredientes(){const busca=($("#buscaIngredientes").value||"").toLowerCase();const lista=state.ingredientes.filter(i=>(i.nome||"").toLowerCase().includes(busca)||String(i.codigo||"").toLowerCase().includes(busca));const tbody=$("#tabelaIngredientes");if(!lista.length){tbody.innerHTML=`<tr><td colspan="6" class="empty-table">Nenhum ingrediente cadastrado.</td></tr>`;return;}tbody.innerHTML=lista.sort((a,b)=>(Number(a.codigo)||99999)-(Number(b.codigo)||99999)||a.nome.localeCompare(b.nome)).map(i=>`<tr><td>${textoSeguro(i.codigo||"-")}</td><td><strong>${textoSeguro(i.nome)}</strong></td><td>${formatarNumero(i.quantidade)} ${textoSeguro(i.unidadeCompra)}</td><td>${formatarMoeda(i.custoTotal)}</td><td>${formatarCustoBase(custoUnitarioIngrediente(i))} / ${unidadeBase(i.unidadeCompra)}</td><td><div class="action-buttons"><button class="btn secondary" onclick="editarIngrediente('${i.id}')">Editar</button><button class="btn danger" onclick="excluirIngrediente('${i.id}')">Excluir</button></div></td></tr>`).join("");}
function salvarCusto(e){e.preventDefault();if(!exigirAdmin())return;const id=$("#custoId").value,nome=$("#custoNome").value.trim(),categoria=$("#custoCategoria").value,valorMensal=parseMoeda($("#custoValorMensal").value);if(!nome||!categoria||valorMensal<=0){mostrarToast("Preencha corretamente o custo.");return;}const custo={id:id||gerarId("cus"),nome,categoria,valorMensal};state.custos=id?state.custos.map(c=>c.id===id?custo:c):[...state.custos,custo];limparFormCusto();atualizarTudo();mostrarToast(id?"Custo atualizado.":"Custo cadastrado.");}
function editarCusto(id){if(!exigirAdmin())return;const c=state.custos.find(x=>x.id===id);if(!c)return;$("#custoId").value=c.id;$("#custoNome").value=c.nome;$("#custoCategoria").value=c.categoria;$("#custoValorMensal").value=Number(c.valorMensal).toLocaleString("pt-BR",{minimumFractionDigits:2});$("#cancelarEdicaoCusto").classList.remove("hidden");document.querySelector('[data-tab="custos"]').click();}
function excluirCusto(id){if(!exigirAdmin())return;if(!confirm("Excluir este custo?"))return;state.custos=state.custos.filter(c=>c.id!==id);atualizarTudo();mostrarToast("Custo excluído.");}function limparFormCusto(){$("#formCusto").reset();$("#custoId").value="";$("#cancelarEdicaoCusto").classList.add("hidden");}
function salvarConfigCustos(){if(!exigirAdmin())return;const horas=Number($("#horasProdutivasMes").value);if(!Number.isFinite(horas)||horas<0){mostrarToast("Informe uma capacidade produtiva válida.");return;}state.config.horasProdutivasMes=horas;atualizarTudo();mostrarToast("Capacidade produtiva salva.");}function atualizarPreviewCustos(){const input=$("#horasProdutivasMes"),editando=input===document.activeElement;if(input&&!editando)input.value=state.config.horasProdutivasMes??"";const horas=input&&editando?Number(input.value||0):Number(state.config.horasProdutivasMes||0),total=totalCustosFixos(),hora=horas>0?total/horas:0,min=horas>0?total/(horas*60):0;$("#previewTotalCustosFixos").textContent=formatarMoeda(total);$("#previewCustoHora").textContent=formatarMoeda(hora);$("#previewCustoMinuto").textContent=formatarMoeda(min);}
function renderCustos(){const tbody=$("#tabelaCustos");if(!state.custos.length){tbody.innerHTML=`<tr><td colspan="4" class="empty-table">Nenhum custo cadastrado.</td></tr>`;return;}tbody.innerHTML=state.custos.map(c=>`<tr><td><strong>${textoSeguro(c.nome)}</strong></td><td>${textoSeguro(c.categoria)}</td><td>${formatarMoeda(c.valorMensal)}</td><td><div class="action-buttons"><button class="btn secondary" onclick="editarCusto('${c.id}')">Editar</button><button class="btn danger" onclick="excluirCusto('${c.id}')">Excluir</button></div></td></tr>`).join("");}
function adicionarLinhaIngredienteReceita(item={}){const div=document.createElement("div");div.className="recipe-ingredient-row";div.innerHTML=`<select class="receitaIngredienteSelect" required></select><input type="number" class="receitaIngredienteQuantidade" min="0" step="0.001" placeholder="Qtd." value="${item.quantidade||""}" required /><select class="receitaIngredienteUnidade" required><option value="">Unidade</option><option value="g" ${normalizarUnidade(item.unidade)==="g"?"selected":""}>g</option><option value="ml" ${normalizarUnidade(item.unidade)==="ml"?"selected":""}>ml</option><option value="unidade" ${normalizarUnidade(item.unidade)==="unidade"?"selected":""}>unidade</option></select><button type="button" class="btn danger removerIngredienteReceita">Remover</button>`;div.querySelector(".removerIngredienteReceita").addEventListener("click",()=>{div.remove();if(!$("#listaIngredientesReceita").children.length)adicionarLinhaIngredienteReceita();atualizarPreviewReceita();});$("#listaIngredientesReceita").appendChild(div);atualizarSelectsIngredientes();if(item.ingredienteId)div.querySelector(".receitaIngredienteSelect").value=item.ingredienteId;atualizarPreviewReceita();}
function atualizarSelectsIngredientes(){$$(".receitaIngredienteSelect").forEach(sel=>{const old=sel.value;sel.innerHTML=`<option value="">Selecione um ingrediente</option>`+state.ingredientes.slice().sort((a,b)=>(Number(a.codigo)||9999)-(Number(b.codigo)||9999)||a.nome.localeCompare(b.nome)).map(i=>`<option value="${i.id}">${textoSeguro(i.codigo?i.codigo+" - ":"")}${textoSeguro(i.nome)} — ${formatarCustoBase(custoUnitarioIngrediente(i))}/${unidadeBase(i.unidadeCompra)}</option>`).join("");sel.value=old;});}
function coletarIngredientesReceita(){return $$("#listaIngredientesReceita .recipe-ingredient-row").map(row=>({ingredienteId:row.querySelector(".receitaIngredienteSelect").value,quantidade:Number(row.querySelector(".receitaIngredienteQuantidade").value),unidade:normalizarUnidade(row.querySelector(".receitaIngredienteUnidade").value)})).filter(i=>i.ingredienteId||i.quantidade||i.unidade);}
function salvarReceita(e){e.preventDefault();if(!exigirAdmin())return;const id=$("#receitaId").value,nome=$("#receitaNome").value.trim(),categoria=$("#receitaCategoria").value,ingredientes=coletarIngredientesReceita();if(!nome||!categoria){mostrarToast("Informe nome e categoria da ficha.");return;}if(!ingredientes.length||ingredientes.some(i=>!i.ingredienteId||i.quantidade<=0||!i.unidade)){mostrarToast("Confira os ingredientes da ficha técnica.");return;}const receita={id:id||gerarId("rec"),nome,categoria,setorPreparo:normalizarSetorPreparo($("#receitaSetorPreparo").value),rendimento:$("#receitaRendimento").value.trim(),tempoPreparoMin:tempoParaMinutos($("#receitaTempoPreparo").value),ingredientes,modoPreparo:$("#receitaModoPreparo").value.trim(),observacoes:$("#receitaObservacoes").value.trim(),apresentacao:$("#receitaApresentacao").value.trim(),ativoCardapio:$("#receitaAtivoCardapio").value==="true",descricaoCardapio:$("#receitaDescricaoCardapio").value.trim(),fotoProduto:$("#receitaFotoProduto").value||"",fotoUrl:$("#receitaFotoUrl").value.trim(),precoFinalManual:parseMoeda($("#receitaPrecoFinal").value)};state.receitas=id?state.receitas.map(r=>r.id===id?receita:r):[...state.receitas,receita];limparFormReceita();atualizarTudo();mostrarToast(id?"Ficha atualizada.":"Ficha técnica cadastrada.");}
function editarReceita(id){if(!exigirAdmin())return;const r=state.receitas.find(x=>x.id===id);if(!r)return;$("#receitaId").value=r.id;$("#receitaNome").value=r.nome;$("#receitaCategoria").value=r.categoria;$("#receitaSetorPreparo").value=normalizarSetorPreparo(r.setorPreparo||"auto");$("#receitaRendimento").value=r.rendimento||"";$("#receitaTempoPreparo").value=tempoParaMinutos(r.tempoPreparoMin??r.tempoPreparo)||"";$("#receitaModoPreparo").value=r.modoPreparo||"";$("#receitaObservacoes").value=r.observacoes||"";$("#receitaApresentacao").value=r.apresentacao||"";$("#receitaAtivoCardapio").value=r.ativoCardapio?"true":"false";$("#receitaDescricaoCardapio").value=r.descricaoCardapio||"";$("#receitaPrecoFinal").value=r.precoFinalManual?Number(r.precoFinalManual).toLocaleString("pt-BR",{minimumFractionDigits:2}):"";$("#receitaFotoProduto").value=r.fotoProduto||"";$("#receitaFotoUrl").value=r.fotoUrl||"";mostrarFotoPreview(r.fotoProduto||r.fotoUrl);$("#listaIngredientesReceita").innerHTML="";(r.ingredientes||[]).forEach(adicionarLinhaIngredienteReceita);$("#cancelarEdicaoReceita").classList.remove("hidden");document.querySelector('[data-tab="receitas"]').click();atualizarPreviewReceita();}
function excluirReceita(id){if(!exigirAdmin())return;if(!confirm("Excluir esta ficha técnica?"))return;state.receitas=state.receitas.filter(r=>r.id!==id);atualizarTudo();mostrarToast("Ficha excluída.");}function limparFormReceita(){$("#formReceita").reset();$("#receitaId").value="";$("#receitaFotoProduto").value="";$("#listaIngredientesReceita").innerHTML="";adicionarLinhaIngredienteReceita();$("#cancelarEdicaoReceita").classList.add("hidden");mostrarFotoPreview("");atualizarPreviewReceita();}
function atualizarPreviewReceita(){const temp={ingredientes:coletarIngredientesReceita(),tempoPreparoMin:tempoParaMinutos($("#receitaTempoPreparo").value),precoFinalManual:parseMoeda($("#receitaPrecoFinal").value)};const c=calcularReceita(temp);$("#previewCustoIngredientes").textContent=formatarMoeda(c.custoIngredientes);$("#previewCustoFixoReceita").textContent=formatarMoeda(c.custoTempo);$("#previewCustoTotalReceita").textContent=formatarMoeda(c.custoTotal);$("#previewPrecoSugerido").textContent=formatarMoeda(c.precoSugeridoBruto);$("#previewPrecoArredondado").textContent=formatarMoeda(c.precoArredondado);$("#previewMargem").innerHTML=`<span class="margin-badge ${classeMargem(c.margem)}">${c.margem.toFixed(1)}%</span>`;}
function carregarFotoProduto(e){const f=e.target.files[0];if(!f)return;if(f.size>700000){mostrarToast("Imagem muito grande. Use uma foto menor para não pesar o navegador.");return;}const reader=new FileReader();reader.onload=()=>{$("#receitaFotoProduto").value=reader.result;mostrarFotoPreview(reader.result);};reader.readAsDataURL(f);}function removerFotoProduto(){$("#receitaFotoProduto").value="";$("#receitaFotoInput").value="";$("#receitaFotoUrl").value="";mostrarFotoPreview("");}function mostrarFotoPreview(src){$("#fotoPreviewBox").classList.toggle("hidden",!src);if(src)$("#fotoPreview").src=src;}
function renderReceitas(){const busca=($("#buscaReceitas")?.value||"").toLowerCase();const lista=state.receitas.filter(r=>r.nome.toLowerCase().includes(busca));const tbody=$("#tabelaReceitas");if(!lista.length){tbody.innerHTML=`<tr><td colspan="10" class="empty-table">Nenhuma ficha técnica cadastrada.</td></tr>`;return;}tbody.innerHTML=lista.map(r=>{const c=calcularReceita(r);return`<tr><td><strong>${textoSeguro(r.nome)}</strong>${c.incompleta?`<br><span class="warning-text">Conferir ingredientes</span>`:""}</td><td>${textoSeguro(r.categoria)}</td><td>${textoSeguro(labelSetorPreparo(r.setorPreparo))}</td><td>${formatarMoeda(c.custoTotal)}</td><td>${formatarMoeda(c.precoSugeridoBruto)}</td><td>${formatarMoeda(c.precoArredondado)}</td><td><strong>${formatarMoeda(c.precoFinal)}</strong></td><td><span class="margin-badge ${classeMargem(c.margem)}">${c.margem.toFixed(1)}%</span></td><td>${r.ativoCardapio?"✅ Ativo":"—"}</td><td><div class="action-buttons"><button class="btn secondary" onclick="editarReceita('${r.id}')">Editar</button><button class="btn danger" onclick="excluirReceita('${r.id}')">Excluir</button></div></td></tr>`}).join("");}
function renderDashboard(){$("#totalIngredientes").textContent=state.ingredientes.length;$("#totalReceitas").textContent=state.receitas.length;$("#totalAtivosCardapio").textContent=state.receitas.filter(r=>r.ativoCardapio).length;$("#custoFixoUnitario").textContent=formatarMoeda(custoOperacionalMinuto());const calc=state.receitas.map(r=>({r,c:calcularReceita(r)}));const maior=[...calc].sort((a,b)=>b.c.custoTotal-a.c.custoTotal).slice(0,5);$("#listaMaiorCusto").innerHTML=maior.length?maior.map(x=>`<div class="list-item"><strong>${textoSeguro(x.r.nome)}</strong><span>Custo total: ${formatarMoeda(x.c.custoTotal)}</span></div>`).join(""):`<div class="empty-state">Nenhuma receita cadastrada ainda.</div>`;$("#listaPrecoSugerido").innerHTML=calc.length?calc.slice(0,6).map(x=>`<div class="list-item"><strong>${textoSeguro(x.r.nome)}</strong><span>Preço final: ${formatarMoeda(x.c.precoFinal)} · Margem ${x.c.margem.toFixed(1)}%</span></div>`).join(""):`<div class="empty-state">Cadastre receitas para visualizar os preços.</div>`;const avisos=calc.filter(x=>x.c.incompleta||x.c.margem<50);$("#listaAvisosReceitas").innerHTML=avisos.length?avisos.map(x=>`<div class="list-item"><strong>${textoSeguro(x.r.nome)}</strong><span class="warning-text">${x.c.incompleta?"Conferir ingrediente/unidade":"Margem abaixo de 50%"}</span></div>`).join(""):`<div class="empty-state">Nenhum aviso no momento.</div>`;}
function renderSimulador(){const sel=$("#simuladorProduto");if(!sel)return;const old=sel.value;sel.innerHTML=`<option value="">Selecione uma ficha técnica</option>`+state.receitas.map(r=>`<option value="${r.id}">${textoSeguro(r.nome)}</option>`).join("");sel.value=old;renderSimuladorResultado();}function renderSimuladorResultado(){const id=$("#simuladorProduto").value,r=state.receitas.find(x=>x.id===id),box=$("#simuladorResultado");if(!r){box.innerHTML=`<div class="empty-state">Selecione um produto para simular.</div>`;return;}const c=calcularReceita(r);box.innerHTML=`<div class="sim-card"><span>Produto</span><strong>${textoSeguro(r.nome)}</strong></div><div class="sim-card"><span>Custo calculado</span><strong>${formatarMoeda(c.custoTotal)}</strong></div><div class="sim-card"><span>Preço atual/final</span><strong>${formatarMoeda(c.precoFinal)}</strong></div><div class="sim-card"><span>Lucro bruto</span><strong>${formatarMoeda(c.lucroBruto)}</strong></div><div class="sim-card"><span>Margem</span><strong><span class="margin-badge ${classeMargem(c.margem)}">${c.margem.toFixed(1)}%</span></strong></div><div class="sim-card"><span>Markup real</span><strong>${c.markupReal.toFixed(2)}x</strong></div>`;}
function renderTreinamento(){const busca=($("#buscaTreinamento").value||"").toLowerCase(),cat=$("#filtroCategoriaTreinamento").value,role=roleAtual();const lista=state.receitas.filter(r=>r.nome.toLowerCase().includes(busca)&&(!cat||r.categoria===cat)&&(role==="admin"||AtendimentoStore.itemPertenceAoSetor({setorPreparo:r.setorPreparo,categoria:r.categoria},role,r)));const cont=$("#cardsTreinamento");if(!lista.length){cont.innerHTML=`<div class="card empty-state">Nenhuma receita encontrada para treinamento.</div>`;return;}cont.innerHTML=lista.map(r=>{const itens=(r.ingredientes||[]).map(item=>{const ing=state.ingredientes.find(i=>i.id===item.ingredienteId);return`<li>${formatarNumero(item.quantidade)} ${item.unidade} — ${textoSeguro(ing?ing.nome:"Ingrediente não encontrado")}</li>`}).join("");return`<article class="card training-card"><h3>${textoSeguro(r.nome)}</h3><div class="training-meta">${textoSeguro(r.categoria)}${r.rendimento?` • Rendimento: ${textoSeguro(r.rendimento)}`:""}${tempoParaMinutos(r.tempoPreparoMin)?` • Tempo: ${tempoParaMinutos(r.tempoPreparoMin)} min`:""}</div><div class="training-section"><h4>Ingredientes</h4><ul>${itens}</ul></div><div class="training-section"><h4>Modo de preparo</h4><p>${textoSeguro(r.modoPreparo||"Nenhum modo de preparo informado.")}</p></div><div class="training-section"><h4>Padrão de apresentação</h4><p>${textoSeguro(r.apresentacao||"Nenhum padrão informado.")}</p></div><div class="training-section"><h4>Observações</h4><p>${textoSeguro(r.observacoes||"Nenhuma observação informada.")}</p></div></article>`}).join("");}
function prepararQr(){const url=state.config.cardapioUrl||location.href.replace(/index\.html.*$/,"cardapio.html").replace(/#.*$/,"cardapio.html");$("#cardapioUrl").value=url;if(state.config.cardapioUrl)gerarQrCode(false);}function gerarQrCode(show=true){if(show&&!exigirAdmin())return;const url=$("#cardapioUrl").value.trim();if(!url){mostrarToast("Informe a URL do cardápio.");return;}state.config.cardapioUrl=url;salvarDados();const src=`https://api.qrserver.com/v1/create-qr-code/?size=640x640&margin=24&data=${encodeURIComponent(url)}`;$("#qrPreview").innerHTML=`<img src="${src}" alt="QR Code do cardápio Capivaras" />`;const a=$("#baixarQrCode");a.href=src;a.classList.remove("hidden");if(show)mostrarToast("QR Code gerado.");}
async function importarCsvDiretorio(){if(!exigirAdmin())return;try{const resp=await fetch("custos.csv",{cache:"no-store"});if(!resp.ok)throw new Error();const txt=await resp.text();importarIngredientesDeCsv(txt,"custos.csv");}catch{mostrarToast("Não encontrei custos.csv. Rode em localhost ou use importação manual.");}}function importarCsvManual(){if(!exigirAdmin())return;const file=$("#importarCsvInput").files[0];if(!file){mostrarToast("Selecione um arquivo CSV.");return;}const reader=new FileReader();reader.onload=()=>importarIngredientesDeCsv(reader.result,file.name);reader.readAsText(file,"UTF-8");}
function detectarSeparador(linha){return(linha.match(/;/g)||[]).length>=(linha.match(/,/g)||[]).length?";":",";}function parseCsv(text){text=String(text||"").replace(/^\uFEFF/,"");const sep=detectarSeparador(text.split(/\r?\n/)[0]||"");const rows=[];let row=[],cell="",inside=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&inside&&next==='"'){cell+='"';i++;}else if(ch==='"'){inside=!inside;}else if(ch===sep&&!inside){row.push(cell);cell="";}else if((ch==='\n'||ch==='\r')&&!inside){if(ch==='\r'&&next==='\n')i++;row.push(cell);if(row.some(x=>String(x).trim()!==""))rows.push(row);row=[];cell="";}else cell+=ch;}if(cell||row.length){row.push(cell);rows.push(row);}return rows;}function normalizarHeader(h){return String(h||"").replace(/^\uFEFF/,"").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]/g,"");}
function importarIngredientesDeCsv(text,nomeArquivo="CSV"){const rows=parseCsv(text);if(rows.length<2){mostrarToast("CSV sem dados para importar.");return;}const headers=rows[0].map(normalizarHeader);const idxCod=headers.findIndex(h=>["cod","codigo","codig","cd"].includes(h));const idxNome=headers.findIndex(h=>["ingredientes","ingrediente","nome","produto","item"].includes(h));const idxQtd=headers.findIndex(h=>["quantidade","qtd","qtde"].includes(h));const idxUn=headers.findIndex(h=>["unidadedemedida","unidade","un"].includes(h));const idxValor=headers.findIndex(h=>["valor","custototal","custo","preco","precofinal"].includes(h));if(idxNome<0||idxQtd<0||idxUn<0||idxValor<0){mostrarToast("Não reconheci as colunas do CSV. Use: Cód.; Ingredientes; Quantidade; Unidade de medida; Valor.");return;}let novos=0,atualizados=0;rows.slice(1).forEach((r,n)=>{const codigo=String(r[idxCod]||"").trim(),nome=String(r[idxNome]||"").trim(),quantidade=Number(String(r[idxQtd]||"").replace(",",".")),unidadeCompra=normalizarUnidade(r[idxUn]),custoTotal=parseMoeda(r[idxValor]);if(!nome||quantidade<=0||custoTotal<=0)return;let existente=state.ingredientes.find(i=>(codigo&&String(i.codigo||"")===codigo)||i.nome.trim().toLowerCase()===nome.toLowerCase());const item={id:existente?.id||gerarId("ing"),codigo,nome,quantidade,unidadeCompra,custoTotal,origem:nomeArquivo,linhaOrigem:n+2,atualizadoEm:new Date().toISOString()};if(existente){Object.assign(existente,item);atualizados++;}else{state.ingredientes.push(item);novos++;}});atualizarTudo();mostrarToast(`CSV importado. Novos: ${novos}. Atualizados: ${atualizados}.`);}
function importarReceitasCsvManual(){if(!exigirAdmin())return;const file=$("#importarReceitasInput").files[0];if(!file){mostrarToast("Selecione o CSV de receitas.");return;}const reader=new FileReader();reader.onload=()=>importarReceitasDeCsv(reader.result,file.name);reader.readAsText(file,"UTF-8");}
function importarReceitasDeCsv(text,nomeArquivo="receitas.csv"){const rows=parseCsv(text);if(rows.length<2){mostrarToast("CSV de receitas sem dados.");return;}const h=rows[0].map(normalizarHeader);const idxPrato=h.findIndex(x=>["prato","receita","nomedareceita","nomereceita","produto"].includes(x));const idxCod=h.findIndex(x=>["codigo","cod","codig"].includes(x));const idxIng=h.findIndex(x=>["ingrediente","ingredientes"].includes(x));const idxQtd=h.findIndex(x=>["quantidade","qtd","qtde"].includes(x));const idxTempo=h.findIndex(x=>["tempo","tempopreparo","tempopreparomin"].includes(x));const idxCat=h.findIndex(x=>["categoria"].includes(x));const idxPreco=h.findIndex(x=>["preco","precofinal","valorfinal"].includes(x));const idxDesc=h.findIndex(x=>["descricao","descricaocardapio"].includes(x));const idxAtivo=h.findIndex(x=>["ativo","ativocardapio","cardapio"].includes(x));if(idxPrato<0||idxCod<0||idxQtd<0){mostrarToast("Modelo inválido. Use: Prato;Código;Ingrediente;Quantidade;Tempo.");return;}const grupos={};let naoEncontrados=[];rows.slice(1).forEach(r=>{const prato=String(r[idxPrato]||"").trim();if(!prato)return;const codigo=String(r[idxCod]||"").trim();const nomeIng=idxIng>=0?String(r[idxIng]||"").trim():"";const ing=state.ingredientes.find(i=>String(i.codigo||"")===codigo)||(nomeIng?state.ingredientes.find(i=>i.nome.trim().toLowerCase()===nomeIng.toLowerCase()):null);if(!ing){naoEncontrados.push(codigo||nomeIng);return;}if(!grupos[prato])grupos[prato]={nome:prato,categoria:idxCat>=0?String(r[idxCat]||"Outro").trim()||"Outro":"Outro",tempoPreparoMin:idxTempo>=0?tempoParaMinutos(r[idxTempo]):0,precoFinalManual:idxPreco>=0?parseMoeda(r[idxPreco]):0,descricaoCardapio:idxDesc>=0?String(r[idxDesc]||"").trim():"",ativoCardapio:idxAtivo>=0?/^(sim|s|true|1|ativo)$/i.test(String(r[idxAtivo]||"")):false,ingredientes:[]};if(idxTempo>=0&&tempoParaMinutos(r[idxTempo]))grupos[prato].tempoPreparoMin=tempoParaMinutos(r[idxTempo]);grupos[prato].ingredientes.push({ingredienteId:ing.id,codigo:ing.codigo,quantidade:Number(String(r[idxQtd]||"").replace(",",".")),unidade:unidadeBase(ing.unidadeCompra)});});let criadas=0,atualizadas=0;Object.values(grupos).forEach(g=>{if(!g.ingredientes.length)return;let existente=state.receitas.find(r=>r.nome.trim().toLowerCase()===g.nome.trim().toLowerCase());const receita={...(existente||{}),id:existente?.id||gerarId("rec"),nome:g.nome,categoria:g.categoria||existente?.categoria||"Outro",rendimento:existente?.rendimento||"",tempoPreparoMin:g.tempoPreparoMin||existente?.tempoPreparoMin||0,ingredientes:g.ingredientes,modoPreparo:existente?.modoPreparo||"",observacoes:existente?.observacoes||`Importado de ${nomeArquivo}`,apresentacao:existente?.apresentacao||"",ativoCardapio:g.ativoCardapio||existente?.ativoCardapio||false,descricaoCardapio:g.descricaoCardapio||existente?.descricaoCardapio||"",fotoProduto:existente?.fotoProduto||"",fotoUrl:existente?.fotoUrl||"",precoFinalManual:g.precoFinalManual||existente?.precoFinalManual||0};if(existente){state.receitas=state.receitas.map(r=>r.id===existente.id?receita:r);atualizadas++;}else{state.receitas.push(receita);criadas++;}});atualizarTudo();mostrarToast(`Receitas importadas. Criadas: ${criadas}. Atualizadas: ${atualizadas}.${naoEncontrados.length?" Códigos não encontrados: "+naoEncontrados.slice(0,5).join(", "):""}`);}
function exportarCsvIngredientes(){if(!exigirAdmin())return;const headers=["Cód.","Ingredientes","Quantidade","Unidade de medida","Valor"];const linhas=state.ingredientes.map(i=>[i.codigo||"",i.nome,i.quantidade,i.unidadeCompra,Number(i.custoTotal||0).toFixed(2).replace(".",",")]);const csv=[headers,...linhas].map(r=>r.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(";")).join("\n");baixarArquivo(csv,"capivaras-ingredientes-atualizado.csv","text/csv;charset=utf-8");mostrarToast("CSV de ingredientes exportado.");}
function dadosCardapio(){return{geradoEm:new Date().toISOString(),receitas:state.receitas.filter(r=>r.ativoCardapio).map(r=>{const c=calcularReceita(r);return{id:r.id,nome:r.nome,categoria:r.categoria,setorPreparo:normalizarSetorPreparo(r.setorPreparo||"auto"),descricaoCardapio:r.descricaoCardapio,ingredientes:(r.ingredientes||[]).map(it=>state.ingredientes.find(i=>i.id===it.ingredienteId)?.nome).filter(Boolean),precoFinal:c.precoFinal,fotoProduto:r.fotoProduto||r.fotoUrl||""};})};}
function exportarCardapioJson(){if(!exigirAdmin())return;baixarArquivo(JSON.stringify(dadosCardapio(),null,2),"cardapio-data.json","application/json");mostrarToast("cardapio-data.json exportado.");}
function exportarJson(){if(!exigirAdmin())return;const backup={...state,pedidos:AtendimentoStore.carregarPedidos(),comandas:AtendimentoStore.carregarComandas(),configuracaoAtendimento:AtendimentoStore.carregarConfiguracao(),mesas:AtendimentoStore.carregarMesas()};baixarArquivo(JSON.stringify(backup,null,2),"capivaras-ficha-tecnica-backup.json","application/json");mostrarToast("Backup JSON exportado.");}
function importarJson(){if(!exigirAdmin())return;const file=$("#importarJsonInput").files[0];if(!file){mostrarToast("Selecione um arquivo JSON.");return;}const reader=new FileReader();reader.onload=()=>{try{const dados=JSON.parse(reader.result);if(!dados.ingredientes||!dados.receitas){mostrarToast("Arquivo JSON inválido.");return;}if(!confirm("Importar este JSON substituirá os dados atuais. Continuar?"))return;state={ingredientes:dados.ingredientes||[],custos:dados.custos||[],receitas:dados.receitas||[],config:dados.config||{}};if(Array.isArray(dados.pedidos))AtendimentoStore.salvarPedidos(dados.pedidos);if(dados.comandas)AtendimentoStore.salvarComandas(dados.comandas);if(dados.configuracaoAtendimento)AtendimentoStore.salvarConfiguracao(dados.configuracaoAtendimento);if(Array.isArray(dados.mesas))AtendimentoStore.salvarMesas(dados.mesas);migrarDados();atualizarTudo();mostrarToast("JSON importado.");}catch{mostrarToast("Erro ao importar JSON.");}};reader.readAsText(file);}
function baixarArquivo(conteudo,nome,tipo){const blob=new Blob([conteudo],{type:tipo});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=nome;a.click();URL.revokeObjectURL(url);}function limparTodosDados(){if(!exigirAdmin())return;if(!confirm("Tem certeza que deseja limpar todos os dados salvos neste navegador?"))return;state={ingredientes:[],custos:[],receitas:[],config:{horasProdutivasMes:220,cardapioUrl:""}};localStorage.removeItem(STORAGE_KEY);AtendimentoStore.removerTudo();limparFormIngrediente();limparFormCusto();limparFormReceita();atualizarTudo(false);mostrarToast("Dados removidos.");}
function renderConfigAtendimento(){if(!$("#modoAtendimento"))return;const config=AtendimentoStore.carregarConfiguracao();$("#modoAtendimento").value=config.modo;$("#resumoAtendimento").innerHTML=config.modo==="pedidos"?`<strong>Cardápio + pedidos</strong><span>O cliente usa o QR Code da mesa, monta o carrinho e envia o pedido.</span>`:`<strong>Apenas cardápio</strong><span>O cliente visualiza o cardápio e pede diretamente no balcão.</span>`;}
function salvarConfigAtendimento(){if(!exigirAdmin())return;AtendimentoStore.salvarConfiguracao({modo:$("#modoAtendimento").value});renderConfigAtendimento();renderPedidosAdmin();mostrarToast("Modo de atendimento salvo.");}
function labelTipoCobranca(v){return v==="comanda"?"Comanda":"Pagar na entrega";}
function formatarDataHora(iso){if(!iso)return"-";return new Date(iso).toLocaleString("pt-BR",{dateStyle:"short",timeStyle:"short"});}
function atualizarContadoresPedidos(pedidos){const cont={Novo:0,"Em preparo":0,Pronto:0,Entregue:0,Cancelado:0};pedidos.forEach(p=>{cont[p.status||"Novo"]=(cont[p.status||"Novo"]||0)+1;});$("#pedidosCountNovo").textContent=cont.Novo||0;$("#pedidosCountEmPreparo").textContent=cont["Em preparo"]||0;$("#pedidosCountPronto").textContent=cont.Pronto||0;$("#pedidosCountEntregue").textContent=cont.Entregue||0;$("#pedidosCountCancelado").textContent=cont.Cancelado||0;}
function preencherFiltroMesasPedidos(pedidos){const select=$("#filtroPedidoMesa");if(!select)return;const atual=select.value;const numeros=[...AtendimentoStore.carregarMesas().map(m=>m.numero),...pedidos.map(p=>p.mesa)].filter(Boolean);const unicos=[...new Set(numeros)].sort((a,b)=>Number(a)-Number(b)||String(a).localeCompare(String(b)));select.innerHTML=`<option value="">Todas as mesas</option>`+unicos.map(m=>`<option value="${textoSeguro(m)}">Mesa ${textoSeguro(m)}</option>`).join("");select.value=unicos.includes(atual)?atual:"";}
function produtoDoPedidoItem(item){return state.receitas.find(r=>r.id===item.produtoId||r.id===item.id)||item;}
function itensPedidoPorVisao(pedido,visao){const itens=Array.isArray(pedido.itens)?pedido.itens:[];if(visao==="geral")return itens;return itens.filter(item=>AtendimentoStore.itemPertenceAoSetor(item,visao,produtoDoPedidoItem(item)));}
function pedidoPassaFiltros(pedido){const mesa=$("#filtroPedidoMesa")?.value,status=$("#filtroPedidoStatus")?.value,data=$("#filtroPedidoData")?.value,cobranca=$("#filtroPedidoCobranca")?.value;if(mesa&&pedido.mesa!==mesa)return false;if(status&&(pedido.status||"Novo")!==status)return false;if(data&&String(pedido.criadoEm||"").slice(0,10)!==data)return false;if(cobranca&&pedido.tipoCobranca!==cobranca)return false;return true;}
function renderPedidosAdmin(){if(!$("#listaPedidosAdmin"))return;renderConfigAtendimento();aplicarPermissoesPerfil();const pedidos=AtendimentoStore.carregarPedidos(),role=roleAtual(),visao=role==="admin"?(pedidoVisaoAtual||"geral"):role;const pedidosVisiveis=role==="admin"?pedidos:pedidos.filter(p=>itensPedidoPorVisao(p,role).length);preencherFiltroMesasPedidos(pedidosVisiveis);atualizarContadoresPedidos(pedidosVisiveis);const filtrados=pedidosVisiveis.filter(pedidoPassaFiltros).map(p=>({pedido:p,itens:itensPedidoPorVisao(p,visao)})).filter(x=>x.itens.length||visao==="geral");const board=$("#listaPedidosAdmin");if(!filtrados.length){board.innerHTML=`<div class="card empty-state">Nenhum pedido encontrado para os filtros atuais.</div>`;return;}board.innerHTML=AtendimentoStore.status.map(status=>{const grupo=filtrados.filter(x=>(x.pedido.status||"Novo")===status);return`<section class="order-column"><div class="panel-title"><h3>${textoSeguro(status)}</h3><span>${grupo.length}</span></div>${grupo.length?grupo.map(renderPedidoCard).join(""):`<div class="empty-state">Sem pedidos.</div>`}</section>`;}).join("");}
function renderPedidoCard({pedido,itens}){const subtotal=itens.reduce((a,i)=>a+Number(i.subtotal||Number(i.precoUnitario||0)*Number(i.quantidade||0)),0),visao=roleAtual()==="admin"?pedidoVisaoAtual:roleAtual(),total=visao==="geral"?Number(pedido.total||subtotal):subtotal;const itensHtml=itens.map(i=>`<li><strong>${textoSeguro(i.nome)}</strong><span>${formatarNumero(i.quantidade)} x ${formatarMoeda(i.precoUnitario)} = ${formatarMoeda(i.subtotal||Number(i.precoUnitario||0)*Number(i.quantidade||0))}</span></li>`).join("");return`<article class="order-card"><header><div><strong>#${textoSeguro(pedido.numero||"-")}</strong><span>Mesa ${textoSeguro(pedido.mesa||"-")}</span></div><span class="status-pill">${textoSeguro(pedido.status||"Novo")}</span></header><div class="order-meta"><span>${textoSeguro(pedido.nomeCliente||"Cliente")}</span><span>${labelTipoCobranca(pedido.tipoCobranca)}</span><span>${formatarDataHora(pedido.criadoEm)}</span></div><ul class="order-items">${itensHtml}</ul>${pedido.observacao?`<p class="order-note"><strong>Obs.:</strong> ${textoSeguro(pedido.observacao)}</p>`:""}<div class="order-total"><span>Total</span><strong>${formatarMoeda(total)}</strong></div><div class="action-buttons order-actions"><button class="btn secondary" type="button" onclick="atualizarStatusPedidoAdmin('${pedido.id}','Em preparo')">Aceitar pedido</button><button class="btn secondary" type="button" onclick="atualizarStatusPedidoAdmin('${pedido.id}','Em preparo')">Em preparo</button><button class="btn secondary" type="button" onclick="atualizarStatusPedidoAdmin('${pedido.id}','Pronto')">Pronto</button><button class="btn secondary" type="button" onclick="atualizarStatusPedidoAdmin('${pedido.id}','Entregue')">Entregue</button><button class="btn danger" type="button" onclick="atualizarStatusPedidoAdmin('${pedido.id}','Cancelado')">Cancelar</button></div></article>`;}
function atualizarStatusPedidoAdmin(id,status){const original=AtendimentoStore.carregarPedidos().find(p=>p.id===id),role=roleAtual();if(!original){mostrarToast("Pedido não encontrado.");return;}if(role!=="admin"&&!itensPedidoPorVisao(original,role).length){mostrarToast("Seu perfil não pode alterar este pedido.");return;}const pedido=AtendimentoStore.atualizarStatusPedido(id,status);if(!pedido){mostrarToast("Não foi possível atualizar o pedido.");return;}renderPedidosAdmin();renderResumoDados();mostrarToast(`Pedido #${pedido.numero} atualizado para ${status}.`);}
function urlPadraoCardapio(){const limpa=location.href.split("#")[0].split("?")[0];return limpa.endsWith("index.html")?limpa.replace(/index\.html$/,"cardapio.html"):limpa.replace(/\/$/,"")+"/cardapio.html";}
function montarLinkMesa(base,mesa){base=String(base||"cardapio.html").trim()||"cardapio.html";const hash=base.includes("#")?"#"+base.split("#").slice(1).join("#"):"";const semHash=base.split("#")[0];if(!/^(https?:|file:|\/\/)/i.test(semHash)){const sep=semHash.includes("?")?"&":"?";return `${semHash}${sep}mesa=${encodeURIComponent(mesa)}${hash}`;}try{const url=new URL(semHash,location.href);url.searchParams.set("mesa",mesa);return url.href+hash;}catch{const sep=semHash.includes("?")?"&":"?";return `${semHash}${sep}mesa=${encodeURIComponent(mesa)}${hash}`;}}
function qrCodeSrc(link){return`https://api.qrserver.com/v1/create-qr-code/?size=640x640&margin=24&data=${encodeURIComponent(link)}`;}
function gerarMesasAdmin(){if(!exigirAdmin())return;const qtd=Number($("#quantidadeMesas").value),base=$("#urlBaseMesas").value.trim()||urlPadraoCardapio();if(!Number.isFinite(qtd)||qtd<=0){mostrarToast("Informe uma quantidade de mesas válida.");return;}state.config.cardapioUrl=base;salvarDados();const agora=new Date().toISOString();const mesas=Array.from({length:qtd},(_,i)=>{const numero=String(i+1).padStart(2,"0"),link=montarLinkMesa(base,numero);return{id:gerarId("mesa"),numero,link,qrCodeUrl:qrCodeSrc(link),ativo:true,criadoEm:agora};});AtendimentoStore.salvarMesas(mesas);renderMesasQr();prepararQr();mostrarToast(`${qtd} mesa(s) gerada(s).`);}
function renderMesasQr(){if(!$("#listaMesasQr"))return;const mesas=AtendimentoStore.carregarMesas(),base=state.config.cardapioUrl||urlPadraoCardapio();if($("#urlBaseMesas")!==document.activeElement)$("#urlBaseMesas").value=base;if($("#quantidadeMesas")!==document.activeElement)$("#quantidadeMesas").value=mesas.length||"";$("#exemploLinksMesas").innerHTML=`<strong>Exemplos</strong><span>Mesa 01 → ${textoSeguro(montarLinkMesa(base,"01"))}</span><span>Mesa 02 → ${textoSeguro(montarLinkMesa(base,"02"))}</span>`;const box=$("#listaMesasQr");if(!mesas.length){box.classList.add("empty-state");box.innerHTML="Informe a quantidade de mesas para gerar os links.";return;}box.classList.remove("empty-state");box.innerHTML=mesas.map(m=>{const link=m.link||montarLinkMesa(base,m.numero),src=m.qrCodeUrl||qrCodeSrc(link);return`<article class="mesa-qr-item"><div class="mesa-qr-copy"><strong>Mesa ${textoSeguro(m.numero)}</strong><a href="${textoSeguro(link)}" target="_blank" rel="noopener">${textoSeguro(link)}</a></div><img src="${src}" alt="QR Code da mesa ${textoSeguro(m.numero)}" /><a class="btn secondary" href="${src}" download="mesa-${textoSeguro(m.numero)}-qrcode-capivaras.png">Baixar PNG</a></article>`;}).join("");}
function renderResumoDados(){const pedidos=AtendimentoStore.carregarPedidos(),configAtendimento=AtendimentoStore.carregarConfiguracao(),mesas=AtendimentoStore.carregarMesas();const resumo={ingredientes:state.ingredientes.length,custosFixos:state.custos.length,receitas:state.receitas.length,ativosNoCardapio:state.receitas.filter(r=>r.ativoCardapio).length,horasProdutivasMes:state.config.horasProdutivasMes,custoOperacionalMinuto:custoOperacionalMinuto(),modoAtendimento:configAtendimento.modo==="pedidos"?"Cardápio + pedidos":"Apenas cardápio",pedidos:pedidos.length,mesas:mesas.length,ultimaAtualizacao:new Date().toLocaleString("pt-BR")};$("#resumoDados").textContent=JSON.stringify(resumo,null,2);}window.editarIngrediente=editarIngrediente;window.excluirIngrediente=excluirIngrediente;window.editarCusto=editarCusto;window.excluirCusto=excluirCusto;window.editarReceita=editarReceita;window.excluirReceita=excluirReceita;window.atualizarStatusPedidoAdmin=atualizarStatusPedidoAdmin;
